package com.wipro.spring; import java.util.List; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.ui.Model; @Controller public class SeriesController { @GetMapping("/") public String home(){return "index";} @GetMapping("/series") public String series(Model model){model.addAttribute("series",List.of("Breaking Bad","Friends","Dark","Sherlock","Stranger Things","The Office","Suits","The Crown","Narcos","Money Heist"));return "result";} }